```rust
wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

use crate::aap::caps::kb_read;

struct Node;

const MAX_QUESTION_BYTES: usize = 512;

/// Enforces the `ensures len(question) <= 512` postcondition defensively, cutting
/// at a char boundary. The `requires` clause already guarantees this for valid
/// inputs, so this only ever changes a value that would otherwise violate it.
fn bounded(question: String) -> String {
    if question.len() <= MAX_QUESTION_BYTES {
        return question;
    }
    let mut end = MAX_QUESTION_BYTES;
    while !question.is_char_boundary(end) {
        end -= 1;
    }
    question[..end].to_string()
}

impl Guest for Node {
    fn run(query: ModeratedQuery) -> ConversationContext {
        let intent = query.query.intent;
        let question = bounded(query.query.question);
        let knowledge = kb_read::lookup(&question);

        ConversationContext {
            intent,
            question,
            knowledge,
        }
    }
}

export!(Node);
```

